using System.Runtime.InteropServices;
namespace LSE.AutoCADElectrical.CatalogTools;public static class DiagnosticsService{public static string BuildReport(){var s=SettingsService.Load();var x=new List<string>{"LSE Catalog Tools V2",RuntimeInformation.FrameworkDescription,"Assembly: "+typeof(DiagnosticsService).Assembly.Location,"Catalog: "+s.CatalogPath,"Catalog exists: "+File.Exists(s.CatalogPath),"Standards: "+s.CompanyStandardsPath,"Vault path: "+s.CatalogVaultPath};try{x.Add("Tables: "+new AccessCatalogService(s.CatalogPath).GetTables().Count);x.Add("Catalog read: PASS");}catch(Exception ex){x.Add("Catalog read: FAIL "+ex.Message);}x.Add("");x.Add(VaultCatalogService.TestReport(s,connect:false));return string.Join(Environment.NewLine,x);}}
